// Tangkap pesan error dari node sebelumnya (AI Agent)
// Jika undefined, gunakan string kosong agar tidak crash
const rawError = $json.error?.message || $json.error || "Unknown Error";
const errorString = String(rawError).toLowerCase();

// Siapkan pesan default jika error-nya aneh/tidak dikenali
let friendlyMessage = "Maaf, sistem saat ini sedang mengalami gangguan teknis. Silakan coba beberapa saat lagi.";

// Deteksi spesifik: Limit Token / Quota Habis (Error 429)
if (errorString.includes("429") || errorString.includes("too many request") || errorString.includes("quota")) {
    friendlyMessage = "Maaf, sistem sedang melayani banyak permintaan (antrean penuh). Mohon tunggu sekitar 1 menit lalu coba lagi.";
} 
// Deteksi spesifik: Timeout / Otak AI lelet mikir
else if (errorString.includes("timeout") || errorString.includes("econnreset")) {
    friendlyMessage = "Maaf, koneksi otak AI kami sedang lambat. Pertanyaanmu gagal diproses karena waktu tunggu habis (Timeout).";
} 
// Deteksi spesifik: API Key salah / Server AI mati (Error 401 / 403)
else if (errorString.includes("401") || errorString.includes("403") || errorString.includes("authentication")) {
    friendlyMessage = "Sistem AI sedang dalam perbaikan jaringan. (Kode: Auth Error). Hubungi administrator.";
}

// Format output untuk dikembalikan ke Vercel (sesuaikan key "text" dengan frontend-mu)
return {
    text: friendlyMessage,
    // Kita tetap kirim raw_error untuk kebutuhan debugging di console browser (optional)
    debug_error: rawError 
};
